import React, { PureComponent } from 'react';
import cls from 'classnames';
import PropTypes from 'prop-types';
import '@douyinfe/semi-foundation/timeline/timeline.scss';
import { cssClasses, strings } from '@douyinfe/semi-foundation/timeline/constants';
import getDataAttr from '@douyinfe/semi-foundation/utils/getDataAttr';
import ConfigContext from '../configProvider/context';
import Item, { TimelineItemProps } from './item';

export type { TimelineItemProps } from './item';

export interface Data extends TimelineItemProps {
    content: React.ReactNode
}

export interface TimelineProps extends Pick<React.AriaAttributes, 'aria-label'> {
    mode?: 'left' | 'right' | 'center' | 'alternate';
    className?: string;
    style?: React.CSSProperties;
    dataSource?: Data[];
    children?: React.ReactNode
}

const prefixCls = cssClasses.PREFIX;

class Timeline extends PureComponent<TimelineProps> {
    static contextType = ConfigContext;
    static Item = Item;
    static propTypes = {
        mode: PropTypes.oneOf(strings.MODE),
        className: PropTypes.string,
        style: PropTypes.object,
        dataSource: PropTypes.array,
    };
    static defaultProps = {
        mode: 'left',
    };

    getPosCls = (ele: React.ReactElement, idx: number) => {
        const { mode } = this.props;
        if (mode === 'alternate') {
            if (ele.props.position) {
                return `${prefixCls}-item-${ele.props.position}`;
            }
            return idx % 2 === 0 ? `${prefixCls}-item-left` : `${prefixCls}-item-right`;
        }
        if (mode === 'center') {
            if (ele.props.position) {
                return `${prefixCls}-item-${ele.props.position}`;
            }
            return `${prefixCls}-item-left`;
        }
        if (mode === 'left' || mode === 'right') {
            return `${prefixCls}-item-${mode}`;
        }
        if (ele.props.position) {
            return `${prefixCls}-item-${ele.props.position}`;
        }
        return '';
    };

    addClassName = (items: React.ReactNode) => React.Children.map(items, (ele, idx) => {
        if (React.isValidElement(ele)) {
            return React.cloneElement(ele, {
                // @ts-ignore
                className: cls(
                    ele.props.className,
                    this.getPosCls(ele, idx)
                ),
            });
        }
        return ele;
    });

    render() {
        const { children, className, style, mode, dataSource, ...rest } = this.props;
        const classString = cls(
            prefixCls,
            className,
            { [`${prefixCls}-${mode}`]: mode }
        );
        let childrenList;
        if (dataSource && dataSource.length) {
            const items = dataSource.map(
                (item, index) => <Item key={`timeline-item-${index}`} {...item}>{item.content}</Item>
            );
            childrenList = this.addClassName(items);
        }
        const items = childrenList || this.addClassName(children);

        return (
            <ul aria-label={this.props['aria-label']} style={style} className={classString} {...getDataAttr(rest)}>
                {items}
            </ul>
        );
    }
}

export default Timeline;

import React, { PureComponent } from 'react';
import cls from 'classnames';
import { noop } from 'lodash';
import PropTypes from 'prop-types';
import { cssClasses, strings } from '@douyinfe/semi-foundation/timeline/constants';
import getDataAttr from '@douyinfe/semi-foundation/utils/getDataAttr';
import '@douyinfe/semi-foundation/timeline/timeline.scss';

export interface TimelineItemProps {
    color?: string;
    children?: React.ReactNode;
    time?: React.ReactNode;
    type?: 'default' | 'ongoing' | 'success' | 'warning' | 'error';
    dot?: React.ReactNode;
    extra?: React.ReactNode;
    position?: 'left' | 'right';
    className?: string;
    style?: React.CSSProperties;
    onClick?: React.MouseEventHandler<HTMLLIElement>
}

const prefixCls = cssClasses.ITEM;

export default class Item extends PureComponent<TimelineItemProps> {
    static propTypes = {
        color: PropTypes.string,
        time: PropTypes.node,
        type: PropTypes.oneOf(strings.ITEM_TYPE),
        dot: PropTypes.node,
        extra: PropTypes.node,
        position: PropTypes.oneOf(strings.ITEM_POS),
        className: PropTypes.string,
        style: PropTypes.object,
        onClick: PropTypes.func,
    };

    static defaultProps = {
        type: 'default',
        time: '',
        onClick: noop,
    };

    render() {
        const {
            className,
            color,
            children,
            dot,
            type,
            style,
            time,
            extra,
            onClick,
            ...rest
        } = this.props;

        const itemCls = cls(prefixCls,
            className
        );

        const dotCls = cls({
            [`${prefixCls}-head`]: true,
            [`${prefixCls}-head-custom`]: dot,
            [`${prefixCls}-head-${type}`]: type,
        });
        const dotStyle = color ? { style: { backgroundColor: color } } : null;
        return (
            <li className={itemCls} style={style} onClick={onClick} {...getDataAttr(rest)}>
                <div className={`${prefixCls}-tail`} aria-hidden />
                <div
                    className={dotCls}
                    aria-hidden
                    {...dotStyle}
                >
                    {dot}
                </div>
                <div className={`${prefixCls}-content`}>
                    {children}
                    {extra && <div className={`${prefixCls}-content-extra`}>{extra}</div>}
                    {time && <div className={`${prefixCls}-content-time`}>{time}</div>}
                </div>
            </li>
        );
    }
}

