        const isHide = currentTime > 0 && currentTime < totalTime;
        if (!isPlaying && poster) {
            return (
                <img 
                    className={cls(`${prefixCls}-poster`, 
                        { [`${prefixCls}-poster-hide`]: isHide }
                    )}
                    src={poster} 
                    alt="poster" 
                />
