import { memo, useMemo, useState, useRef, useEffect } from "react";
import { Action, ObjectType, Tab, State } from "../../data/constants";
import {
  Input,
  Button,
  ButtonGroup,
  Popover,
  Divider,
} from "@douyinfe/semi-ui";
import ColorPicker from "../EditorSidePanel/ColorPicker";
import {
  IconEdit,
  IconDeleteStroked,
  IconLock,
  IconUnlock,
} from "@douyinfe/semi-icons";
import {
  useLayout,
  useUndoRedo,
  useSelect,
  useNotes,
  useSaveState,
  useTransform,
  useSettings,
} from "../../hooks";
import { useTranslation } from "react-i18next";
import { noteWidth, noteRadius, noteFold } from "../../data/constants";

export default memo(function Note({ data, onPointerDown }) {
  const [editField, setEditField] = useState({});
  const [hovered, setHovered] = useState(false);
  const [resizing, setResizing] = useState(false);
  const initialWidthRef = useRef(data.width ?? noteWidth);
  const initialXRef = useRef(data.x);
  const { layout } = useLayout();
  const { t } = useTranslation();
  const { setSaveState } = useSaveState();
  const { updateNote, deleteNote } = useNotes();
  const { setUndoStack, setRedoStack } = useUndoRedo();
  const { transform } = useTransform();
  const { settings } = useSettings();
  const {
    selectedElement,
    setSelectedElement,
    bulkSelectedElements,
    setBulkSelectedElements,
  } = useSelect();
  const initialColorRef = useRef(data.color);

  const handleColorPick = (color) => {
    setUndoStack((prev) => {
      let undoColor = initialColorRef.current;
      const lastColorChange = prev.findLast(
        (e) =>
          e.element === ObjectType.NOTE &&
          e.nid === data.id &&
          e.action === Action.EDIT &&
          e.redo?.color,
      );
      if (lastColorChange) {
        undoColor = lastColorChange.redo.color;
      }

      if (color === undoColor) return prev;

      const newStack = [
        ...prev,
        {
          action: Action.EDIT,
          element: ObjectType.NOTE,
          nid: data.id,
          undo: { color: undoColor },
          redo: { color: color },
          message: t("edit_note", {
            noteTitle: data.title,
            extra: "[color]",
          }),
        },
      ];
      return newStack;
    });
    setRedoStack([]);
  };

  const handleChange = (e) => {
    const textarea = document.getElementById(`note_${data.id}`);
    if (!textarea) return;
    textarea.style.height = "0";
    textarea.style.height = textarea.scrollHeight + "px";
    const newHeight = textarea.scrollHeight + 42;
    const updates = { content: e.target.value };
    if (newHeight !== data.height) {
      updates.height = newHeight;
    }
    updateNote(data.id, updates);
  };

  const handleBlur = (e) => {
    if (e.target.value === editField.content) return;
    const textarea = document.getElementById(`note_${data.id}`);
    textarea.style.height = "0";
    textarea.style.height = textarea.scrollHeight + "px";
    const newHeight = textarea.scrollHeight + 16 + 20 + 4;
    setUndoStack((prev) => [
      ...prev,
      {
        action: Action.EDIT,
        element: ObjectType.NOTE,
        nid: data.id,
        undo: editField,
        redo: { content: e.target.value, height: newHeight },
        message: t("edit_note", {
          noteTitle: e.target.value,
          extra: "[content]",
        }),
      },
    ]);
    setRedoStack([]);
  };

  const lockUnlockNote = (e) => {
    const locking = !data.locked;
    updateNote(data.id, { locked: locking });

    const lockNote = () => {
      setSelectedElement({
        ...selectedElement,
        element: ObjectType.NONE,
        id: -1,
        open: false,
      });
      setBulkSelectedElements((prev) =>
        prev.filter((el) => el.id !== data.id || el.type !== ObjectType.NOTE),
      );
    };

    const unlockNote = () => {
      const elementInBulk = {
        id: data.id,
        type: ObjectType.NOTE,
        initialCoords: { x: data.x, y: data.y },
        currentCoords: { x: data.x, y: data.y },
      };
      if (e.ctrlKey || e.metaKey) {
        setBulkSelectedElements((prev) => [...prev, elementInBulk]);
      } else {
        setBulkSelectedElements([elementInBulk]);
      }
      setSelectedElement((prev) => ({
        ...prev,
        element: ObjectType.NOTE,
        id: data.id,
        open: false,
      }));
    };

    if (locking) {
      lockNote();
    } else {
      unlockNote();
    }
  };

  const edit = () => {
    setSelectedElement((prev) => ({
      ...prev,
      ...(layout.sidebar && { currentTab: Tab.NOTES }),
      ...(!layout.sidebar && { element: ObjectType.NOTE }),
      id: data.id,
      open: true,
    }));

    if (layout.sidebar && selectedElement.currentTab === Tab.NOTES) {
      document
        .getElementById(`scroll_note_${data.id}`)
        .scrollIntoView({ behavior: "smooth" });
    }
  };

  const isSelected = useMemo(() => {
    return (
      (selectedElement.id === data.id &&
        selectedElement.element === ObjectType.NOTE) ||
      bulkSelectedElements.some(
        (e) => e.type === ObjectType.NOTE && e.id === data.id,
      )
    );
  }, [selectedElement, data, bulkSelectedElements]);

  const width = data.width ?? noteWidth;
  const MIN_NOTE_WIDTH = 120;

  useEffect(() => {
    const textarea = document.getElementById(`note_${data.id}`);
    if (!textarea) return;

    textarea.style.height = "0";
    const scrollHeight = textarea.scrollHeight;
    textarea.style.height = scrollHeight + "px";
    const newHeight = scrollHeight + 42;

    if (newHeight === data.height) return;

    updateNote(data.id, { height: newHeight });
  }, [data.id, data.height, updateNote]);

  return (
    <g
      onPointerEnter={(e) => e.isPrimary && setHovered(true)}
      onPointerLeave={(e) => e.isPrimary && setHovered(false)}
      onPointerDown={(e) => {
        // Required for onPointerLeave to trigger when a touch pointer leaves
        // https://stackoverflow.com/a/70976017/1137077
        e.target.releasePointerCapture(e.pointerId);
      }}
      onDoubleClick={edit}
    >
      <path
        d={`M${data.x + noteFold} ${data.y} L${data.x + width - noteRadius} ${
          data.y
        } A${noteRadius} ${noteRadius} 0 0 1 ${data.x + width} ${data.y + noteRadius} L${data.x + width} ${
          data.y + data.height - noteRadius
        } A${noteRadius} ${noteRadius} 0 0 1 ${data.x + width - noteRadius} ${data.y + data.height} L${
          data.x + noteRadius
        } ${data.y + data.height} A${noteRadius} ${noteRadius} 0 0 1 ${data.x} ${
          data.y + data.height - noteRadius
        } L${data.x} ${data.y + noteFold}`}
        fill={data.color}
        stroke={
          hovered
            ? "rgb(59 130 246)"
            : isSelected
              ? "rgb(59 130 246)"
              : "rgb(168 162 158)"
        }
        strokeDasharray={hovered ? 5 : 0}
        strokeLinejoin="round"
        strokeWidth="2"
      />
      <path
        d={`M${data.x} ${data.y + noteFold} L${data.x + noteFold - noteRadius} ${
          data.y + noteFold
        } A${noteRadius} ${noteRadius} 0 0 0 ${data.x + noteFold} ${data.y + noteFold - noteRadius} L${
          data.x + noteFold
        } ${data.y} L${data.x} ${data.y + noteFold} Z`}
        fill={data.color}
        stroke={
          hovered
            ? "rgb(59 130 246)"
            : isSelected
              ? "rgb(59 130 246)"
              : "rgb(168 162 158)"
        }
        strokeDasharray={hovered ? 5 : 0}
        strokeLinejoin="round"
        strokeWidth="2"
      />

      {!layout.readOnly && !data.locked && hovered && (
        <g style={{ pointerEvents: "none" }}>
          <circle
            cx={data.x}
            cy={data.y + data.height / 2}
            r={6}
            fill={settings.mode === "light" ? "white" : "rgb(28, 31, 35)"}
            stroke="#5891db"
            strokeWidth={2}
            opacity={1}
          />
          <circle
            cx={data.x + width}
            cy={data.y + data.height / 2}
            r={6}
            fill={settings.mode === "light" ? "white" : "rgb(28, 31, 35)"}
            stroke="#5891db"
            strokeWidth={2}
            opacity={1}
          />
        </g>
      )}
      {!layout.readOnly && !data.locked && (
        <rect
          x={data.x - 4}
          y={data.y + 8}
          width={8}
          height={Math.max(0, data.height - 16)}
          fill="transparent"
          stroke="transparent"
          style={{ cursor: "ew-resize" }}
          onPointerDown={(e) => {
            e.stopPropagation();
            initialWidthRef.current = data.width ?? noteWidth;
            initialXRef.current = data.x;
            setResizing(true);
            e.currentTarget.setPointerCapture?.(e.pointerId);
          }}
          onPointerMove={(e) => {
            if (!resizing) return;
            const delta = e.movementX / (transform?.zoom || 1);
            const currentWidth = data.width ?? noteWidth;
            let proposedWidth = currentWidth - delta;
            let proposedX = data.x + delta;
            if (proposedWidth < MIN_NOTE_WIDTH) {
              const clampDelta = currentWidth - MIN_NOTE_WIDTH;
              proposedWidth = MIN_NOTE_WIDTH;
              proposedX = data.x + clampDelta;
            }
            if (proposedWidth !== data.width || proposedX !== data.x) {
              updateNote(data.id, { width: proposedWidth, x: proposedX });
            }
          }}
          onPointerUp={(e) => {
            if (!resizing) return;
            setResizing(false);
            e.stopPropagation();
            const finalWidth = data.width ?? noteWidth;
            const finalX = data.x;
            const startWidth = initialWidthRef.current;
            const startX = initialXRef.current;
            if (finalWidth !== startWidth || finalX !== startX) {
              setUndoStack((prev) => [
                ...prev,
                {
                  action: Action.EDIT,
                  element: ObjectType.NOTE,
                  nid: data.id,
                  undo: { width: startWidth, x: startX },
                  redo: { width: finalWidth, x: finalX },
                  message: t("edit_note", {
                    noteTitle: data.title,
                    extra: "[width/x]",
                  }),
                },
              ]);
              setRedoStack([]);
            }
          }}
        />
      )}

      {!layout.readOnly && !data.locked && (
        <rect
          x={data.x + width - 4}
          y={data.y + 8}
          width={8}
          height={Math.max(0, data.height - 16)}
          fill="transparent"
          stroke="transparent"
          style={{ cursor: "ew-resize" }}
          onPointerDown={(e) => {
            e.stopPropagation();
            initialWidthRef.current = data.width ?? noteWidth;
            setResizing(true);
            e.currentTarget.setPointerCapture?.(e.pointerId);
          }}
          onPointerMove={(e) => {
            if (!resizing) return;
            const delta = e.movementX / (transform?.zoom || 1);
            const next = Math.max(
              MIN_NOTE_WIDTH,
              (data.width ?? noteWidth) + delta,
            );
            if (next !== data.width) {
              updateNote(data.id, { width: next });
            }
          }}
          onPointerUp={(e) => {
            if (!resizing) return;
            setResizing(false);
            e.stopPropagation();
            const finalWidth = data.width ?? noteWidth;
            const startWidth = initialWidthRef.current;
            if (finalWidth !== startWidth) {
              setUndoStack((prev) => [
                ...prev,
                {
                  action: Action.EDIT,
                  element: ObjectType.NOTE,
                  nid: data.id,
                  undo: { width: startWidth },
                  redo: { width: finalWidth },
                  message: t("edit_note", {
                    noteTitle: data.title,
                    extra: "[width]",
                  }),
                },
              ]);
              setRedoStack([]);
            }
          }}
        />
      )}
      <foreignObject
        x={data.x}
        y={data.y}
        width={width}
        height={data.height}
        onPointerDown={() => onPointerDown(data, ObjectType.NOTE)}
      >
        <div className="text-gray-900 select-none w-full h-full cursor-move px-3 py-2">
          <div className="flex justify-between gap-1 w-full">
            <label
              htmlFor={`note_${data.id}`}
              className="ms-5 overflow-hidden text-ellipsis"
            >
              {data.title}
            </label>
            {(hovered ||
              (selectedElement.element === ObjectType.NOTE &&
                selectedElement.id === data.id &&
                selectedElement.open &&
                !layout.sidebar)) && (
              <ButtonGroup
                type="tertiary"
                size="small"
                aria-label={t("note_actions")}
              >
                <Button
                  size="small"
                  type="tertiary"
                  icon={
                    data.locked ? (
                      <IconLock size="small" />
                    ) : (
                      <IconUnlock size="small" />
                    )
                  }
                  onClick={lockUnlockNote}
                  disabled={layout.readOnly}
                />
                <Popover
                  visible={
                    selectedElement.element === ObjectType.NOTE &&
                    selectedElement.id === data.id &&
                    selectedElement.open &&
                    !layout.sidebar
                  }
                  onClickOutSide={() => {
                    if (selectedElement.editFromToolbar) {
                      setSelectedElement((prev) => ({
                        ...prev,
                        editFromToolbar: false,
                      }));
                      return;
                    }
                    setSelectedElement((prev) => ({
                      ...prev,
                      open: false,
                    }));
                    setSaveState(State.SAVING);
                  }}
                  stopPropagation
                  content={
                    <div className="popover-theme">
                      <div className="font-semibold mb-2 ms-1">{t("edit")}</div>
                      <div className="w-[280px] flex items-center mb-2">
                        <Input
                          value={data.title}
                          placeholder={t("title")}
                          className="me-2"
                          readonly={layout.readOnly}
                          onChange={(value) =>
                            updateNote(data.id, { title: value })
                          }
                          onFocus={(e) =>
                            setEditField({ title: e.target.value })
                          }
                          onBlur={(e) => {
                            if (e.target.value === editField.title) return;
                            setUndoStack((prev) => [
                              ...prev,
                              {
                                action: Action.EDIT,
                                element: ObjectType.NOTE,
                                nid: data.id,
                                undo: editField,
                                redo: { title: e.target.value },
                                message: t("edit_note", {
                                  noteTitle: e.target.value,
                                  extra: "[title]",
                                }),
                              },
                            ]);
                            setRedoStack([]);
                          }}
                        />
                        <ColorPicker
                          usePopover={true}
                          readOnly={layout.readOnly}
                          value={data.color}
                          onChange={(color) => updateNote(data.id, { color })}
                          onColorPick={(color) => handleColorPick(color)}
                        />
                      </div>
                      <Divider />
                      <Button
                        icon={<IconDeleteStroked />}
                        type="danger"
                        theme="borderless"
                        block
                        disabled={layout.readOnly}
                        onClick={() => deleteNote(data.id, true)}
                      >
                        {t("delete")}
                      </Button>
                    </div>
                  }
                  trigger="custom"
                  position="rightTop"
                  showArrow
                >
                  <Button
                    size="small"
                    type="tertiary"
                    icon={<IconEdit size="small" />}
                    onClick={edit}
                  />
                </Popover>
              </ButtonGroup>
            )}
          </div>
          <textarea
            id={`note_${data.id}`}
            readOnly={layout.readOnly}
            value={data.content}
            onChange={handleChange}
            onFocus={(e) =>
              setEditField({
                content: e.target.value,
                height: data.height,
              })
            }
            onBlur={handleBlur}
            className="w-full resize-none outline-hidden overflow-y-hidden border-none select-none"
            style={{ backgroundColor: data.color }}
          />
        </div>
      </foreignObject>
    </g>
  );
});

src/components/EditorCanvas/Relationship:
import {
  memo,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { Cardinality, ObjectType, Tab } from "../../data/constants";
import { calcPath, calcCompositePath } from "../../utils/calcPath";
import { useSettings, useLayout, useSelect, useDiagram } from "../../hooks";
import { SelectActionsContext } from "../../context/SelectContext";
import { useTranslation } from "react-i18next";
import { SideSheet } from "@douyinfe/semi-ui";
import RelationshipInfo from "../EditorSidePanel/RelationshipsTab/RelationshipInfo";
import {
  getVisibleFieldEntries,
  getRelationshipFields,
  getTableWidth,
} from "../../utils/utils";

const labelFontSize = 16;
const cardinalityOffset = 28;

export default memo(function Relationship({
  data,
  startTable,
  endTable,
  startRelatedFieldKeys,
  endRelatedFieldKeys,
}) {
  const { layout } = useLayout();
  const { setSelectedElement } = useContext(SelectActionsContext);

  const edit = useCallback(() => {
    setSelectedElement((prev) => ({
      ...prev,
      ...(layout.sidebar && { currentTab: Tab.RELATIONSHIPS }),
      element: ObjectType.RELATIONSHIP,
      id: data.id,
      open: true,
    }));
    if (layout.sidebar) {
      document
        .getElementById(`scroll_ref_${data.id}`)
        ?.scrollIntoView({ behavior: "smooth" });
    }
  }, [data.id, layout.sidebar, setSelectedElement]);

  return (
    <RelationshipPath
      data={data}
      startTable={startTable}
      endTable={endTable}
      startRelatedFieldKeys={startRelatedFieldKeys}
      endRelatedFieldKeys={endRelatedFieldKeys}
      onEdit={edit}
    />
  );
});

export function RelationshipEditSheet() {
  const { layout } = useLayout();
  const { selectedElement, setSelectedElement } = useSelect();
  const { relationships } = useDiagram();
  const { t } = useTranslation();

  const data =
    selectedElement.element === ObjectType.RELATIONSHIP &&
    selectedElement.open &&
    !layout.sidebar
      ? relationships.find((r) => r.id === selectedElement.id)
      : null;

  return (
    <SideSheet
      title={t("edit")}
      size="small"
      visible={Boolean(data)}
      onCancel={() => {
        setSelectedElement((prev) => ({
          ...prev,
          open: false,
        }));
      }}
      style={{ paddingBottom: "16px" }}
    >
      <div className="sidesheet-theme">
        {data && <RelationshipInfo data={data} />}
      </div>
    </SideSheet>
  );
}

const RelationshipPath = memo(function RelationshipPath({
  data,
  startTable,
  endTable,
  startRelatedFieldKeys,
  endRelatedFieldKeys,
  onEdit,
}) {
  const { settings } = useSettings();
  const { t } = useTranslation();

  const pathValues = useMemo(() => {
    if (!startTable || !endTable || startTable.hidden || endTable.hidden)
      return null;

    const startEntries = getVisibleFieldEntries(
      startTable,
      startRelatedFieldKeys,
    );
    const endEntries = getVisibleFieldEntries(endTable, endRelatedFieldKeys);
    const indexOf = (entries, fieldId) =>
      entries.findIndex(
        ({ field, originalIndex }) =>
          field.id === fieldId || originalIndex === fieldId,
      );

    const pairs = getRelationshipFields(data);

    return {
      startFieldIndex: indexOf(startEntries, data.startFieldId),
      endFieldIndex: indexOf(endEntries, data.endFieldId),
      startFieldIndices: pairs.map((p) =>
        indexOf(startEntries, p.startFieldId),
      ),
      endFieldIndices: pairs.map((p) => indexOf(endEntries, p.endFieldId)),
      startTable: {
        x: startTable.x,
        y: startTable.y,
        width: getTableWidth(startTable),
        comment: startTable.comment,
        fields: startEntries.map(({ field }) => field),
      },
      endTable: {
        x: endTable.x,
        y: endTable.y,
        width: getTableWidth(endTable),
        comment: endTable.comment,
        fields: endEntries.map(({ field }) => field),
      },
    };
  }, [startTable, endTable, startRelatedFieldKeys, endRelatedFieldKeys, data]);

  const isComposite = (pathValues?.startFieldIndices?.length ?? 0) > 1;

  const composite = useMemo(() => {
    if (!pathValues || !isComposite) return null;
    return calcCompositePath(
      {
        startTable: pathValues.startTable,
        endTable: pathValues.endTable,
        startFieldIndices: pathValues.startFieldIndices,
        endFieldIndices: pathValues.endFieldIndices,
      },
      1,
      settings.showComments,
    );
  }, [pathValues, isComposite, settings.showComments]);

  const d = useMemo(() => {
    if (!pathValues) return null;
    if (composite) return composite.path;
    return calcPath(pathValues, 1, settings.showComments);
  }, [pathValues, composite, settings.showComments]);

  const pathRef = useRef();
  const labelRef = useRef();
  const [hovered, setHovered] = useState(false);
  const [anchors, setAnchors] = useState(null);

  useLayoutEffect(() => {
    if (!d || !pathRef.current) {
      setAnchors(null);
      return;
    }

    const labelBox = labelRef.current?.getBBox();
    const labelWidth = labelBox?.width ?? 0;
    const labelHeight = labelBox?.height ?? 0;

    let labelPoint, startPoint, endPoint;
    if (composite) {
      labelPoint = composite.labelPoint;
      startPoint = composite.startCardinality;
      endPoint = composite.endCardinality;
    } else {
      const path = pathRef.current;
      const pathLength = path.getTotalLength();
      labelPoint = path.getPointAtLength(pathLength / 2);
      startPoint = path.getPointAtLength(cardinalityOffset);
      endPoint = path.getPointAtLength(pathLength - cardinalityOffset);
    }

    setAnchors({
      label: {
        x: labelPoint.x - labelWidth / 2,
        y: labelPoint.y + labelHeight / 2,
      },
      start: { x: startPoint.x, y: startPoint.y },
      end: { x: endPoint.x, y: endPoint.y },
    });
  }, [d, composite, data.name, settings.showRelationshipLabels]);

  let cardinalityStart = "1";
  let cardinalityEnd = "1";

  switch (data.cardinality) {
    // the translated values are to ensure backwards compatibility
    case t(Cardinality.MANY_TO_ONE):
    case Cardinality.MANY_TO_ONE:
      cardinalityStart = data.manyLabel || "n";
      cardinalityEnd = "1";
      break;
    case t(Cardinality.ONE_TO_MANY):
    case Cardinality.ONE_TO_MANY:
      cardinalityStart = "1";
      cardinalityEnd = data.manyLabel || "n";
      break;
    case t(Cardinality.ONE_TO_ONE):
    case Cardinality.ONE_TO_ONE:
      cardinalityStart = "1";
      cardinalityEnd = "1";
      break;
    default:
      break;
  }

  if (!d) return null;

  return (
    <g
      className="select-none group"
      onDoubleClick={onEdit}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      {/* invisible wider path for better hover ux */}
      <path
        d={d}
        fill="none"
        stroke="transparent"
        strokeWidth={12}
        cursor="pointer"
      />
      <path
        ref={pathRef}
        d={d}
        className="relationship-path"
        style={{ stroke: hovered ? undefined : data.color }}
        fill="none"
        cursor="pointer"
      />
      {settings.showRelationshipLabels && (
        <text
          x={anchors?.label.x ?? 0}
          y={anchors?.label.y ?? 0}
          fill={data.color ?? (settings.mode === "dark" ? "lightgrey" : "#333")}
          fontSize={labelFontSize}
          fontWeight={500}
          ref={labelRef}
          className="group-hover:fill-sky-600"
        >
          {data.name}
        </text>
      )}
      {anchors && settings.showCardinality && (
        <>
          <CardinalityLabel
            x={anchors.start.x}
            y={anchors.start.y}
            text={cardinalityStart}
            color={data.color}
          />
          <CardinalityLabel
            x={anchors.end.x}
            y={anchors.end.y}
            text={cardinalityEnd}
            color={data.color}
          />
        </>
      )}
    </g>
  );
});

function CardinalityLabel({ x, y, text, color, r = 12, padding = 14 }) {
  const [textWidth, setTextWidth] = useState(0);
  const textRef = useRef(null);

  useEffect(() => {
    if (textRef.current) {
      const bbox = textRef.current.getBBox();
      setTextWidth(bbox.width);
    }
  }, [text]);

  return (
    <g>
      <rect
        x={x - textWidth / 2 - padding / 2}
        y={y - r}
        rx={r}
        ry={r}
        width={textWidth + padding}
        height={r * 2}
        fill={color ?? "grey"}
        className="group-hover:fill-sky-600"
      />
      <text
        ref={textRef}
        x={x}
        y={y}
        fill="white"
        strokeWidth="0.5"
        textAnchor="middle"
        alignmentBaseline="middle"
      >
        {text}
      </text>
    </g>
  );
}

src/components/EditorCanvas/ResizeHandle:
import { useEffect, useRef, useState } from "react";
import { clampTableWidth } from "../../utils/utils";
import { useSettings } from "../../hooks";

const handleRadius = 6;
const handleHitWidth = handleRadius * 2 + 2;
const handleInset = 6;

export default function ResizeHandles({
  x,
  y,
  width,
  height,
  visible,
  onResize,
  onResizeEnd,
  onEngagedChange,
}) {
  const { settings } = useSettings();
  const [active, setActive] = useState(null);
  const [hovered, setHovered] = useState(null);
  const latestRef = useRef(null);
  const detachRef = useRef(null);
  latestRef.current = { x, width, onResize, onResizeEnd, onEngagedChange };

  const engaged = hovered !== null || active !== null;

  useEffect(() => {
    latestRef.current.onEngagedChange?.(engaged);
  }, [engaged]);

  useEffect(() => () => detachRef.current?.(), []);

  const beginResize = (side) => (e) => {
    if (!e.isPrimary) return;
    e.stopPropagation();

    const from = {
      x,
      width,
      clientX: e.clientX,
      pointerId: e.pointerId,
      zoom: e.currentTarget.ownerSVGElement?.getScreenCTM()?.a || 1,
    };
    setActive(side);

    const move = (event) => {
      if (event.pointerId !== from.pointerId) return;

      const latest = latestRef.current;
      const delta = (event.clientX - from.clientX) / from.zoom;
      const next = clampTableWidth(
        side === "left" ? from.width - delta : from.width + delta,
      );
      if (next === latest.width) return;

      latest.onResize(
        side === "left"
          ? { width: next, x: from.x + from.width - next }
          : { width: next },
      );
    };

    const stop = (event) => {
      if (event && event.pointerId !== from.pointerId) return;

      detachRef.current?.();
      detachRef.current = null;
      setActive(null);

      const latest = latestRef.current;
      if (from.width === latest.width && from.x === latest.x) return;
      latest.onResizeEnd(
        { x: from.x, width: from.width },
        { x: latest.x, width: latest.width },
      );
    };

    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
    window.addEventListener("pointercancel", stop);
    detachRef.current = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
      window.removeEventListener("pointercancel", stop);
    };
  };

  const handle = (side) => {
    const edgeX = side === "left" ? x : x + width;
    const barHeight = Math.max(0, height - handleInset * 2);
    return (
      <g key={side}>
        {(visible || engaged) && (
          <circle
            cx={edgeX}
            cy={y + height / 2}
            r={handleRadius}
            fill={settings.mode === "light" ? "white" : "rgb(28, 31, 35)"}
            stroke="#5891db"
            strokeWidth={2}
            className="pointer-events-none"
          />
        )}
        <rect
          x={edgeX - handleHitWidth / 2}
          y={y + handleInset}
          width={handleHitWidth}
          height={barHeight}
          fill="transparent"
          style={{ cursor: "ew-resize", touchAction: "none" }}
          onPointerEnter={(e) => e.isPrimary && setHovered(side)}
          onPointerLeave={(e) => e.isPrimary && setHovered(null)}
          onPointerDown={beginResize(side)}
        />
      </g>
    );
  };

  return (
    <>
      {handle("left")}
      {handle("right")}
    </>
  );
}

